{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공원 일반운동장 100㎡ 평일 낮 2시간 이용 시 운동 경기와 다른 행사 각각의 가산·감면 전 조례 별표 기본 이용료 범위",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 별표 2의 운동시설 중 일반운동장(광장) 항목은 사용기준이 1㎡당 2시간이며, 체육경기 이용료는 5~10원, 기타행사 이용료는 10~20원으로 정해져 있다. 100㎡를 2시간 사용하는 경우 면적과 사용기준이 그대로 적용되므로, 운동 경기(체육경기)의 가산·감면 전 기본 이용료 범위는 500~1,000원, 다른 행사(기타행사)의 범위는 1,000~2,000원이다. 이 금액은 토·공휴일 가산, 야간 가산, 초과시간 할인 등 비고의 가산·감면이 적용되기 전의 별표상 기본 범위이다.",
          "b_ids": "도시공원:별표2#행2"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
